CREATE TABLE IF NOT EXISTS draft_emails (
  id SERIAL PRIMARY KEY,
  "prospectId" INTEGER NOT NULL REFERENCES prospects(id) ON DELETE CASCADE,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  "agentReasoning" TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'sent', 'discarded')),
  "sentAt" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_draft_emails_prospect ON draft_emails("prospectId");
CREATE INDEX IF NOT EXISTS idx_draft_emails_status ON draft_emails(status);
